import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel
cuda_src = r'''
#include <cuda_fp16.h>

extern "C" __global__
void conv_fp16_kernel(const half* __restrict__ input,
                     const half* __restrict__ weight,
                     const half* __restrict__ bias,
                     half* __restrict__ output,
                     int N, int C_in, int H_in, int W_in,
                     int C_out, int K_h, int K_w,
                     int stride_h, int stride_w,
                     int pad_h, int pad_w,
                     int H_out, int W_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int c_out = tmp % C_out;
    int n     = tmp / C_out;

    float sum = bias ? __half2float(bias[c_out]) : 0.0f;

    int h_start = h_out * stride_h - pad_h;
    int w_start = w_out * stride_w - pad_w;

    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int kh = 0; kh < K_h; ++kh) {
            int h_in = h_start + kh;
            if (h_in < 0 || h_in >= H_in) continue;
            for (int kw = 0; kw < K_w; ++kw) {
                int w_in = w_start + kw;
                if (w_in < 0 || w_in >= W_in) continue;

                int input_idx  = ((n * C_in + c_in) * H_in + h_in) * W_in + w_in;
                int weight_idx = ((c_out * C_in + c_in) * K_h + kh) * K_w + kw;

                half hv = input[input_idx];
                half wv = weight[weight_idx];
                sum += __half2float(hv) * __half2float(wv);
            }
        }
    }
    output[idx] = __float2half(sum);
}
'''

# C++ wrapper
cpp_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>

void conv_fp16(at::Tensor input,
               at::Tensor weight,
               at::Tensor bias,
               at::Tensor output,
               int stride_h,
               int stride_w,
               int pad_h,
               int pad_w) {
    const int N     = input.size(0);
    const int C_in  = input.size(1);
    const int H_in  = input.size(2);
    const int W_in  = input.size(3);
    const int C_out = weight.size(0);
    const int K_h   = weight.size(2);
    const int K_w   = weight.size(3);
    const int H_out = output.size(2);
    const int W_out = output.size(3);

    const int total   = N * C_out * H_out * W_out;
    const int threads = 256;
    const int blocks  = (total + threads - 1) / threads;

    const dim3 grid(blocks);
    const dim3 block(threads);
    const auto stream = at::cuda::getCurrentCUDAStream();

    conv_fp16_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<half*>(input.data_ptr()),
        reinterpret_cast<half*>(weight.data_ptr()),
        reinterpret_cast<half*>(bias.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        N, C_in, H_in, W_in,
        C_out, K_h, K_w,
        stride_h, stride_w,
        pad_h, pad_w,
        H_out, W_out
    );
}
'''

# Compile the extension
conv_mod = load_inline(name='conv_fp16_ext',
                       cpp_sources=cpp_src,
                       cuda_sources=cuda_src,
                       functions=['conv_fp16'],
                       verbose=False)

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels  = 3
        self.out_channels = 96
        self.kernel_size  = 11
        self.stride       = 4
        self.padding      = 2

        # Initialise weights like a regular Conv2d
        conv = nn.Conv2d(self.in_channels,
                         self.out_channels,
                         kernel_size=self.kernel_size,
                         stride=self.stride,
                         padding=self.padding,
                         bias=True)
        self.weight = nn.Parameter(conv.weight.detach().clone().half())
        self.bias   = nn.Parameter(conv.bias.detach().clone().half())

    def forward(self, x):
        assert x.is_cuda and x.dtype == torch.float16, "Input must be CUDA half tensor"
        N, C_in, H_in, W_in = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        C_out = self.out_channels

        H_out = (H_in + 2 * P - K) // S + 1
        W_out = (W_in + 2 * P - K) // S + 1

        out = torch.empty((N, C_out, H_out, W_out),
                          device=x.device,
                          dtype=torch.float16)

        conv_mod.conv_fp16(x.contiguous(),
                           self.weight,
                           self.bias,
                           out,
                           S, S,
                           P, P)

        return out
